import { useEffect, useRef, useState } from "react";

// The home-page hero: an isometric line drawing of the car (generated by frontend/hero/build-car.mjs).
// Hovering the car shows a labelled cutaway; hovering the rear wing opens the DRS flap.
// On touch, a tap toggles the same thing. Keys: X for the cutaway, D for DRS.
const WING = /^(mainplane|flap|endplate|beamwing|drs|pylon)/;

export default function CarHero() {
  const [figure, setFigure] = useState(null);
  const root = useRef(null);

  useEffect(() => {
    let live = true;
    import("../hero/carFigure.js").then((m) => live && setFigure(m));
    return () => {
      live = false;
    };
  }, []);

  useEffect(() => {
    if (!figure || !root.current) return undefined;
    const stage = root.current.querySelector(".iso-stage");
    const flaps = [...stage.querySelectorAll("[data-flap]")];
    const readout = root.current.querySelector("[data-readout]");
    const still = matchMedia("(prefers-reduced-motion: reduce)");
    const drs = { x: 0, v: 0, target: 0 };
    let xray = false;
    let frame = 0;
    let last = 0;
    let shown = 0;

    const say = () => {
      const wing = drs.x > 0.6 ? "DRS open" : drs.x > 0.02 ? (drs.target ? "DRS opening" : "DRS closing") : "DRS closed";
      const text = `${xray ? "cutaway · what's inside" : "bodywork on"} · ${wing}`;
      if (readout.textContent !== text) readout.textContent = text;
    };
    const setXray = (on) => {
      if (on === xray) return;
      xray = on;
      stage.classList.toggle("xray", on);
      say();
    };
    // A sub-stepped spring towards the DRS target; the flap shows the nearest prebuilt frame.
    const tick = (now) => {
      const dt = last ? Math.min((now - last) / 1000, 1 / 30) : 1 / 60;
      last = now;
      if (still.matches) {
        drs.x = drs.target;
        drs.v = 0;
      } else {
        for (let i = 0; i < 4; i++) {
          drs.v += (((drs.target - drs.x) * 120 - drs.v * 22) * dt) / 4;
          drs.x += (drs.v * dt) / 4;
        }
        if (Math.abs(drs.target - drs.x) < 5e-4 && Math.abs(drs.v) < 5e-4) {
          drs.x = drs.target;
          drs.v = 0;
        }
      }
      const f = Math.max(0, Math.min(flaps.length - 1, Math.round(drs.x * (flaps.length - 1))));
      if (f !== shown) {
        flaps[shown].style.display = "none";
        flaps[f].style.display = "";
        shown = f;
      }
      say();
      frame = drs.x !== drs.target || drs.v ? requestAnimationFrame(tick) : 0;
    };
    const run = () => {
      if (!frame) {
        last = 0;
        frame = requestAnimationFrame(tick);
      }
    };
    const onWing = (e) => WING.test(e.target.closest?.("[data-name]")?.dataset.name ?? "");

    const move = (e) => {
      if (e.pointerType !== "mouse") return;
      const wing = onWing(e);
      drs.target = wing ? 1 : 0;
      setXray(!wing);
      run();
    };
    const leave = () => {
      drs.target = 0;
      setXray(false);
      run();
    };
    const click = (e) => {
      if (onWing(e)) drs.target = drs.target ? 0 : 1;
      else setXray(!xray);
      run();
    };
    const key = (e) => {
      if (["x", "X", "Enter", " "].includes(e.key)) {
        e.preventDefault();
        setXray(!xray);
      }
      if (e.key === "d" || e.key === "D") {
        drs.target = drs.target ? 0 : 1;
        run();
      }
      if (e.key === "Escape") leave();
    };
    stage.addEventListener("pointermove", move);
    stage.addEventListener("pointerleave", leave);
    stage.addEventListener("click", click);
    stage.addEventListener("keydown", key);
    return () => {
      cancelAnimationFrame(frame);
      stage.removeEventListener("pointermove", move);
      stage.removeEventListener("pointerleave", leave);
      stage.removeEventListener("click", click);
      stage.removeEventListener("keydown", key);
    };
  }, [figure]);

  if (!figure) return <div className="car-hero car-hero--loading" aria-hidden />;
  return (
    <div className="car-hero iso" data-theme="light" ref={root}>
      <style>{figure.CAR_CSS}</style>
      <div dangerouslySetInnerHTML={{ __html: figure.CAR_HTML }} />
    </div>
  );
}
